#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

static int expectedMax(const vector<string>& grid) {
    int n = grid.size(), m = grid[0].size();
    vector<vector<int>> pref(n + 1, vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            pref[i][j] = pref[i - 1][j] + pref[i][j - 1] - pref[i - 1][j - 1]
                         + (grid[i - 1][j - 1] == '1');
    int best = 0;
    for (int x1 = 1; x1 <= n; ++x1)
        for (int y1 = 1; y1 <= m; ++y1)
            for (int x2 = x1; x2 <= n; ++x2)
                for (int y2 = y1; y2 <= m; ++y2) {
                    int area = (x2 - x1 + 1) * (y2 - y1 + 1);
                    int blacks = pref[x2][y2] - pref[x1 - 1][y2] - pref[x2][y1 - 1] + pref[x1 - 1][y1 - 1];
                    if (blacks * 2 == area && area > best) best = area;
                }
    return best;
}
static bool check(const string& exe, const vector<string>& grid, int id) {
    const string inF = "l4a06p1_in.txt", outF = "l4a06p1_out.txt";
    {
        ofstream o(inF);
        o << grid.size() << ' ' << grid[0].size() << '\n';
        for (size_t i = 0; i < grid.size(); ++i) o << grid[i] << '\n';
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream in(outF);
    int got = -1;
    in >> got;
    int want = expectedMax(grid);
    if (code != 0 || got != want) {
        cout << "[FAIL] case " << id << ": expected=" << want
             << ", actual=" << got << ", status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    vector<string> c1 = {"00000", "01111", "00011", "00011"};
    ++total; if (check(exe, c1, 1)) ++passed;  // 样例1
    vector<vector<string>> small;
    small.push_back(vector<string>{"1"});
    small.push_back(vector<string>{"0"});
    small.push_back(vector<string>{"01"});
    small.push_back(vector<string>{"11"});
    small.push_back(vector<string>{"01", "10"});
    small.push_back(vector<string>{"10", "01"});
    small.push_back(vector<string>{"000", "111"});
    small.push_back(vector<string>{"010", "101", "010"});
    for (size_t i = 0; i < small.size(); ++i) {
        ++total; if (check(exe, small[i], 2 + i)) ++passed;
    }
    srand(20240601);
    for (int t = 0; t < 6; ++t) {
        int n = 1 + rand() % 10, m = 1 + rand() % 10;
        vector<string> g;
        for (int i = 0; i < n; ++i) {
            string s;
            for (int j = 0; j < m; ++j) s += (rand() % 2) ? '1' : '0';
            g.push_back(s);
        }
        ++total; if (check(exe, g, 10 + t)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << '\n';
    return passed == total ? 0 : 1;
}

