#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <numeric>
#include <string>
#include <vector>
using namespace std;

static long long expectedMax(const vector<int>& vals, int k) {
    vector<int> a = vals;
    sort(a.begin(), a.end());
    int n = a.size();
    vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + a[i];
    long long best = 0;
    int l = 0;
    for (int r = 0; r < n; ++r) {
        while (a[r] - a[l] > k) ++l;
        best = max(best, (long long)(pref[r + 1] - pref[l]));
    }
    return best;
}
static long long bruteMax(const vector<int>& vals, int k) {
    int n = vals.size();
    long long best = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        if (!mask) continue;
        long long sum = 0, mx = 0, mn = (long long)1e18;
        bool ok = true;
        for (int i = 0; i < n; ++i) if (mask & (1 << i)) {
            sum += vals[i];
            mx = max(mx, (long long)vals[i]);
            mn = min(mn, (long long)vals[i]);
        }
        if (mx - mn <= k) best = max(best, sum);
    }
    return best;
}
static bool check(const string& exe, const vector<int>& vals, int k, int id) {
    const string inF = "l4a06p2_in.txt", outF = "l4a06p2_out.txt";
    {
        ofstream o(inF);
        o << vals.size() << ' ' << k << '\n';
        for (size_t i = 0; i < vals.size(); ++i) o << vals[i] << (i + 1 == vals.size() ? '\n' : ' ');
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream in(outF);
    long long got = -1;
    in >> got;
    long long want = vals.size() <= 12 ? bruteMax(vals, k) : expectedMax(vals, k);
    if (code != 0 || got != want) {
        cout << "[FAIL] case " << id << ": expected=" << want
             << ", actual=" << got << ", status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    ++total; if (check(exe, {1, 2, 3, 1, 2}, 1, 1)) ++passed;  // 样例1
    ++total; if (check(exe, {7}, 0, 2)) ++passed;
    ++total; if (check(exe, {1, 2, 3}, 0, 3)) ++passed;
    ++total; if (check(exe, {5, 5, 5, 5}, 0, 4)) ++passed;
    ++total; if (check(exe, {1, 100}, 100, 5)) ++passed;
    ++total; if (check(exe, {3, 1, 4, 1, 5, 9, 2, 6}, 3, 6)) ++passed;
    srand(20240602);
    for (int t = 0; t < 8; ++t) {
        int n = 1 + rand() % 12;
        vector<int> v(n);
        for (int i = 0; i < n; ++i) v[i] = 1 + rand() % 20;
        int k = rand() % 21;
        ++total; if (check(exe, v, k, 7 + t)) ++passed;
    }
    for (int t = 0; t < 3; ++t) {
        int n = 100 + rand() % 900;
        vector<int> v(n);
        for (int i = 0; i < n; ++i) v[i] = 1 + rand() % 1000;
        int k = rand() % 1001;
        ++total; if (check(exe, v, k, 15 + t)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << '\n';
    return passed == total ? 0 : 1;
}
